  async function exportProjectDocx(project, editor, title) { if (!window.docx) throw new Error('Biblioteca Word no disponible'); const { Document, Paragraph, TextRun, HeadingLevel, ImageRun, Packer } = window.docx; const root = documentHtmlForExport(project, editor); const children = [new Paragraph({ text: title, heading: HeadingLevel.TITLE })]; const blocks = root.querySelectorAll('h1,h2,h3,h4,p,li,blockquote,pre,table,img'); for (const node of blocks) { const tag = node.tagName.toLowerCase(); if (tag === 'img') { const image = await htmlImageData(node.getAttribute('src')); if (image) children.push(new Paragraph({ children: [new ImageRun({ data: Uint8Array.from(atob(image.data), c => c.charCodeAt(0)), transformation: { width: Math.min(520, image.width), height: Math.min(700, image.height) } })] })); continue; } if (tag === 'table') { for (const row of node.querySelectorAll('tr')) children.push(new Paragraph({ children: [new TextRun({ text: Array.from(row.children).map(cell => cell.textContent.trim()).join('    |    '), bold: row.parentElement.tagName.toLowerCase() === 'thead' })] })); continue; } const text = node.textContent.trim(); if (!text) continue; const heading = tag === 'h1' ? HeadingLevel.HEADING_1 : tag === 'h2' ? HeadingLevel.HEADING_2 : tag === 'h3' ? HeadingLevel.HEADING_3 : tag === 'h4' ? HeadingLevel.HEADING_4 : undefined; children.push(new Paragraph({ heading, bullet: tag === 'li' ? { level: 0 } : undefined, children: heading ? [new TextRun({ text, bold: true })] : domRuns(node, window.docx) })); } const doc = new Document({ creator: 'Cut-real AI', title, styles: { default: { document: { run: { font: 'Times New Roman', size: 24 }, paragraph: { spacing: { line: 360, after: 160 } } } } }, sections: [{ properties: { page: { margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } } }, children }] }); downloadBlob(await Packer.toBlob(doc), `${title}.docx`); }
